package com.acaivis.controller; import com.acaivis.repository.OrderRepository; import com.acaivis.repository.ProductRepository; import com.acaivis.model.OrderStatus; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; import java.math.BigDecimal; import java.util.*;
@RestController @RequestMapping("/api/admin/reports") @PreAuthorize("hasRole('ADMIN')") public class ReportController {private final OrderRepository orders;private final ProductRepository products;public ReportController(OrderRepository o,ProductRepository p){orders=o;products=p;} @GetMapping("/summary") public Map<String,Object> summary(){long total=orders.count();long cancelled=orders.countByStatus(OrderStatus.CANCELLED);long delivered=orders.countByStatus(OrderStatus.DELIVERED);Map<String,Object> r=new LinkedHashMap<>();r.put("totalOrders",total);r.put("deliveredOrders",delivered);r.put("cancelledOrders",cancelled);r.put("productsInCatalog",products.count());r.put("availableProducts",products.findByAvailableTrue().size());return r;}}
